export default function Docs({ initialSection }) {
  const [active, setActive] = useState(initialSection ?? 'intro')
  const [menuOpen, setMenuOpen] = useState(false)
  useEffect(() => { setActive(initialSection ?? 'intro'); setMenuOpen(false) }, [initialSection])
  const groups = [...new Set(SECTIONS.map(s => s.group))]
  const activeLabel = SECTIONS.find(s => s.id === active)?.label ?? ''

  return (
    <div className="docs-layout">
      {/* Desktop sidebar */}
      <aside className="docs-sidebar">
        {groups.map(g => (
          <div key={g}>
            <div className="docs-group-title">{g}</div>
            {SECTIONS.filter(s => s.group === g).map(s => (
              <button key={s.id} className={`docs-nav-item ${active === s.id ? 'active' : ''}`} onClick={() => setActive(s.id)}>
                {s.label}
              </button>
            ))}
          </div>
        ))}
      </aside>

      {/* Content */}
      <div className="docs-content">
        {CONTENT[active]}
      </div>

      {/* Mobile bottom nav bar */}
      <div className="docs-mobile-bar">
        <button className="docs-mobile-bar-btn" onClick={() => setMenuOpen(o => !o)}>
          <span>☰</span>
          <span>{activeLabel}</span>
          <span className="docs-mobile-bar-caret">{menuOpen ? '▼' : '▲'}</span>
        </button>
      </div>

      {/* Mobile menu overlay */}
      {menuOpen && (
        <div className="docs-mobile-overlay" onClick={() => setMenuOpen(false)}>
          <div className="docs-mobile-menu" onClick={e => e.stopPropagation()}>
            <div className="docs-mobile-menu-hd">Contents</div>
            {groups.map(g => (
              <div key={g}>
                <div className="docs-mobile-group">{g}</div>
                {SECTIONS.filter(s => s.group === g).map(s => (
                  <button key={s.id}
                    className={`docs-mobile-item ${active === s.id ? 'active' : ''}`}
                    onClick={() => { setActive(s.id); setMenuOpen(false) }}
                  >{s.label}</button>
                ))}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}
